public double getQalys(){
  try {
    Map<Integer,Double> qalys=(Map<Integer,Double>)this.attributes.get(QualityOfLifeModule.QALY);
    double sum=0.0;
    for (  double currQaly : qalys.values()) {
      sum+=currQaly;
    }
    return sum;
  } catch (ClassCastException e) {
    // Handle the exception, e.g., log the error or return a default value
    System.out.println("Error: The QALY attribute is not of the expected type.");
    return 0.0;
  }
}
